const inc = (key, n = 1) => { stats[key] = (stats[key] || 0) + n; };
const files = fs.readdirSync(path.join(process.env.SCRATCH, 'json')).filter((f) => f.endsWith('.json'));
for (const file of files) {
  const wrapper = JSON.parse(fs.readFileSync(path.join(process.env.SCRATCH, 'json', file), 'utf8'));
  const record = wrapper.agent || wrapper.evaluation || {};
  for (const message of record.messages || []) {
    for (const part of message.parts || []) {
      const rendered = format(part);
      if (part.type === 'text' && typeof part.text === 'string') {
        assert(rendered.includes(part.text), 'text part preserved'); inc('text');
      }
      if (part.type === 'reasoning') {
        const val = part.text || part.reasoning || '';
        if (val.trim()) { assert(rendered.includes(val), 'reasoning preserved'); inc('reasoning'); }
      }
      const input = part.input || part.args || {};
      const output = part.output || part.result || {};
      if (part.type === 'tool-fetch_page' && typeof output.content === 'string' && output.content) {
        assert(rendered.includes(output.content), 'fetch_page content preserved'); inc('fetch_page_content');
      }
      if (part.type === 'tool-read_file' && typeof output.content === 'string' && output.content) {
        assert(rendered.includes(output.content), 'read_file content preserved'); inc('read_file_content');
      }
      if (part.type === 'tool-web_search' && Array.isArray(output.results)) {
        assert(rendered.includes(JSON.stringify(output.results, null, 2)), 'all web_search results and descriptions preserved');
        inc('web_search_calls'); inc('web_search_result_items', output.results.length);
      }
      if (part.type === 'tool-bash' && typeof output.stdout === 'string' && output.stdout) {
        assert(rendered.includes(output.stdout), 'bash stdout preserved'); inc('bash_stdout');
      }
      if (part.type === 'tool-bash' && output.stdout_truncated === true) {
        assert(rendered.includes('output.stdout_truncated:\ntrue'), 'stdout truncation flag preserved');
        assert(rendered.includes('stdout was truncated before export'), 'truncation notice rendered');
        inc('stdout_truncation_notices');
      }
      if (part.type === 'tool-write_file' && typeof input.content === 'string' && input.content) {
        assert(rendered.includes(input.content), 'write_file content preserved'); inc('write_file_content');
      }
      if (part.type === 'tool-edit_file') {
        for (const key of ['old_text', 'new_text']) {
          if (typeof input[key] === 'string' && input[key]) { assert(rendered.includes(input[key]), 'edit_file text preserved'); inc('edit_file_text'); }
        }
      }
      if (part.type === 'data-tool-results') {
        assert(rendered.includes(JSON.stringify(part.data, null, 2)), 'data-tool-results preserved'); inc('data_tool_results');
      }
    }
  }
}
