  assert(nested.includes(needle), `nested payload field ${needle}`);
}
assert(format({type: 'data-tool-results', data: {unexpected: 'object payload'}}).includes('object payload'), 'non-array data payload preserved');
assert(format({type: 'future-part', payload: 'future payload'}).includes('future payload'), 'unknown part preserved');
